// binary state, decoded late
assign en = (state == RUN);
// one-hot, decoded early
always @(posedge clk) en_q <= (next_state == RUN);

// Tree: (s0+s1, s2+s3) then their sum
sum_01 = s0 + s1;
sum_23 = s2 + s3;
result = sum_01 + sum_23; // depth 2

// Carry-save attempt:
compressor_3to2(s0, s1, s2, s3, sum, carry);
result = sum + carry; // still high latency from final add

